SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Renal cell' AND "Monotherapy/combination" = 'Combination' AND ("Name of ICI" LIKE '%PD1%' OR "Name of ICI" LIKE '%CTLA-4%');

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Hepatocellular' AND "Monotherapy/combination" = 'Combination' AND "Type of combination" LIKE '%anti-VEGF%';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Type of combination" = 'ICI+Chemo';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Monotherapy/combination" = 'Combination' AND "Name of ICI" LIKE '%PD-L1%' AND "Cancer type" = 'Hepatocellular cancer';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE 1=1 AND "Type of combination" = 'ICI+Chemoradiotherapy';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Multiple Myeloma' AND "Type of combination" = 'ICI+Chemo';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Bladder' AND 1=1 AND "Monotherapy/combination" = 'Monotherapy';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 2' AND "Cancer type" = 'Breast' AND (1=1 OR "Name of ICI" = 'CTLA-4') AND "Monotherapy/combination" = 'Monotherapy';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Monotherapy/combination" = 'Combination' AND 1=1 AND "Cancer type" = 'Multiple Myeloma';
